+import { useEffect, useMemo, useState } from "react";
+import {
+  LineChart,
+  Line,
+  XAxis,
+  YAxis,
+  CartesianGrid,
+  Tooltip,
+  ResponsiveContainer,
+} from "recharts";
+
+type DailyPnL = {
+  date: string;
+  netProfit: number;
+  cumulative: number;
+};
+
+export type MultiStrategyConfigSummary = {
+  rank: number; // global rank used for file naming: config-{rank}-daily.json
+  strategyId?: string;
+  strategyName?: string;
+  strategyRank?: number; // 1..N within strategy (optional)
+  tpLevel: number;
+  slMargin: number;
+  triggerMargin: number;
+  maxRT: number;
+  netProfitTotal: number;
+};
+
+type TimeRange = "1m" | "1y" | "4y";
+
+type MultiStrategyChartProps = {
+  pipelinename: string;
+  configs: MultiStrategyConfigSummary[];
+  defaultSelectedRank?: number;
+  onSelectRank?: (rank: number) => void;
+};
+
+const TIME_RANGE_OPTIONS: Array<{ id: TimeRange; label: string; days: number | null }> = [
+  { id: "1m", label: "1M", days: 30 },
+  { id: "1y", label: "1Y", days: 252 },
+  { id: "4y", label: "4Y", days: null },
+];
+
+function getStrategyKey(config: MultiStrategyConfigSummary): string {
+  return config.strategyId ?? "unknown-strategy";
+}
+
+function getStrategyLabel(config: MultiStrategyConfigSummary): string {
+  return config.strategyName ?? config.strategyId ?? "Unknown strategy";
+}
+
+function buildLineKey(rank: number): string {
+  return `r${rank}`;
+}
+
+function clamp01(v: number): number {
+  return Math.max(0, Math.min(1, v));
+}
+
+function mixRgb(a: [number, number, number], b: [number, number, number], t: number): [number, number, number] {
+  const tt = clamp01(t);
+  return [
+    Math.round(a[0] + (b[0] - a[0]) * tt),
+    Math.round(a[1] + (b[1] - a[1]) * tt),
+    Math.round(a[2] + (b[2] - a[2]) * tt),
+  ];
+}
+
+function rgbToHex([r, g, b]: [number, number, number]): string {
+  const h = (n: number) => n.toString(16).padStart(2, "0");
+  return `#${h(r)}${h(g)}${h(b)}`;
+}
+
+function getStrategyBaseColor(strategyIdx: number): [number, number, number] {
+  // Blue, Teal, Purple, Orange, Green fallback palette
+  const palette: Array<[number, number, number]> = [
+    [45, 156, 255],
+    [16, 185, 129],
+    [168, 85, 247],
+    [249, 115, 22],
+    [34, 197, 94],
+  ];
+  return palette[strategyIdx % palette.length];
+}
+
+function getConfigColor(strategyIdx: number, withinStrategyRank: number | undefined): string {
+  const base = getStrategyBaseColor(strategyIdx);
+  const white: [number, number, number] = [226, 232, 240];
+  const rank = withinStrategyRank ?? 1;
+  // rank=1 should be most saturated; rank=5 slightly closer to white
+  const t = clamp01((rank - 1) / 6);
+  return rgbToHex(mixRgb(base, white, t));
+}
+
+function buildConfigLabel(config: MultiStrategyConfigSummary): string {
+  const sLabel = getStrategyLabel(config);
+  const sRank = config.strategyRank ? `#${config.strategyRank}` : `#${config.rank}`;
+  return `${sLabel} ${sRank} (TP=${config.tpLevel}, SL=${config.slMargin}, TRG=${config.triggerMargin}, RT=${config.maxRT})`;
+}
+
+export default function MultiStrategyChart({ pipelinename, configs, defaultSelectedRank, onSelectRank }: MultiStrategyChartProps) {
+  const [timeRange, setTimeRange] = useState<TimeRange>("4y");
+  const [visibleRanks, setVisibleRanks] = useState<Record<number, boolean>>(() => {
+    const initial: Record<number, boolean> = {};
+    for (const c of configs) initial[c.rank] = true;
+    return initial;
+  });
+  const [dailyByRank, setDailyByRank] = useState<Record<number, DailyPnL[]>>({});
+  const [loading, setLoading] = useState(false);
+  const [error, setError] = useState<string | null>(null);
+
+  // Keep toggle state in sync if config list changes
+  useEffect(() => {
+    setVisibleRanks((prev) => {
+      const next: Record<number, boolean> = { ...prev };
+      for (const c of configs) {
+        if (next[c.rank] === undefined) next[c.rank] = true;
+      }
+      // prune ranks no longer present
+      for (const k of Object.keys(next)) {
+        const rank = Number(k);
+        if (!configs.some((c) => c.rank === rank)) delete next[rank];
+      }
+      return next;
+    });
+  }, [configs]);
+
+  useEffect(() => {
+    let cancelled = false;
+
+    async function loadAllDaily() {
+      try {
+        setLoading(true);
+        setError(null);
+
+        const results = await Promise.all(
+          configs.map(async (c) => {
+            const url = `/data/analysis/${pipelinename}/config-${c.rank}-daily.json`;
+            const res = await fetch(url);
+            if (!res.ok) throw new Error(`Failed to load daily series for config ${c.rank}: ${res.status} ${res.statusText}`);
+            const data = (await res.json()) as unknown;
+            if (!Array.isArray(data)) throw new Error(`Invalid daily series for config ${c.rank}: expected array`);
+            return [c.rank, data as DailyPnL[]] as const;
+          })
+        );
+
+        if (cancelled) return;
+
+        const next: Record<number, DailyPnL[]> = {};
+        for (const [rank, series] of results) next[rank] = series;
+        setDailyByRank(next);
+        setLoading(false);
+      } catch (e) {
+        if (cancelled) return;
+        setError(e instanceof Error ? e.message : "Failed to load chart data");
+        setLoading(false);
+      }
+    }
+
+    loadAllDaily();
+    return () => {
+      cancelled = true;
+    };
+  }, [configs, pipelinename]);
+
+  const { chartData, rankMeta } = useMemo(() => {
+    const strategies = Array.from(
+      new Map(
+        configs.map((c) => [getStrategyKey(c), { key: getStrategyKey(c), label: getStrategyLabel(c) }])
+      ).values()
+    );
+
+    const strategyIndexByKey = new Map<string, number>();
+    strategies.forEach((s, idx) => strategyIndexByKey.set(s.key, idx));
+
+    const meta = new Map<number, { lineKey: string; label: string; color: string }>();
+    for (const c of configs) {
+      const strategyIdx = strategyIndexByKey.get(getStrategyKey(c)) ?? 0;
+      meta.set(c.rank, {
+        lineKey: buildLineKey(c.rank),
+        label: buildConfigLabel(c),
+        color: getConfigColor(strategyIdx, c.strategyRank),
+      });
+    }
+
+    const allDates = new Set<string>();
+    for (const c of configs) {
+      const series = dailyByRank[c.rank];
+      if (!series) continue;
+      for (const d of series) allDates.add(d.date);
+    }
+    const sortedDates = Array.from(allDates).sort();
+
+    const selectedRange = TIME_RANGE_OPTIONS.find((o) => o.id === timeRange) ?? TIME_RANGE_OPTIONS[2];
+    const dateSlice =
+      selectedRange.days === null
+        ? sortedDates
+        : sortedDates.slice(Math.max(0, sortedDates.length - selectedRange.days));
+
+    const dateIndex = new Map<string, number>();
+    dateSlice.forEach((d, idx) => dateIndex.set(d, idx));
+
+    const rows: Array<Record<string, string | number | null>> = dateSlice.map((d) => ({ date: d }));
+
+    for (const c of configs) {
+      const series = dailyByRank[c.rank];
+      if (!series) continue;
+      const key = buildLineKey(c.rank);
+      for (const p of series) {
+        const idx = dateIndex.get(p.date);
+        if (idx === undefined) continue;
+        rows[idx][key] = p.cumulative;
+      }
+    }
+
+    return { chartData: rows, rankMeta: meta };
+  }, [configs, dailyByRank, timeRange]);
+
+  const grouped = useMemo(() => {
+    const groups = new Map<string, { key: string; label: string; items: MultiStrategyConfigSummary[] }>();
+    for (const c of configs) {
+      const key = getStrategyKey(c);
+      const label = getStrategyLabel(c);
+      if (!groups.has(key)) groups.set(key, { key, label, items: [] });
+      groups.get(key)!.items.push(c);
+    }
+    for (const g of groups.values()) {
+      g.items.sort((a, b) => (a.strategyRank ?? a.rank) - (b.strategyRank ?? b.rank));
+    }
+    return Array.from(groups.values());
+  }, [configs]);
+
+  if (error) {
+    return <div className="text-rose-300">Error loading chart: {error}</div>;
+  }
+
+  if (loading && Object.keys(dailyByRank).length === 0) {
+    return <div className="text-slate-400">Loading chart data...</div>;
+  }
+
+  if (chartData.length === 0) {
+    return <div className="text-slate-400">No chart data available</div>;
+  }
+
+  return (
+    <div className="space-y-4">
+      {/* Controls */}
+      <div className="flex flex-wrap items-center justify-between gap-3">
+        <div className="flex items-center gap-2">
+          <div className="text-sm text-slate-400">Range</div>
+          <div className="inline-flex rounded-lg border border-slate-800 bg-slate-950">
+            {TIME_RANGE_OPTIONS.map((opt) => (
+              <button
+                key={opt.id}
+                type="button"
+                onClick={() => setTimeRange(opt.id)}
+                className={`px-3 py-1 text-sm transition-colors ${
+                  timeRange === opt.id ? "bg-emerald-600/20 text-emerald-300" : "text-slate-300 hover:bg-slate-800/40"
+                }`}
+              >
+                {opt.label}
+              </button>
+            ))}
+          </div>
+        </div>
+
+        <div className="text-xs text-slate-500">
+          Click a line (or its label below) to select details.
+        </div>
+      </div>
+
+      {/* Toggles */}
+      <div className="grid gap-3 md:grid-cols-3">
+        {grouped.map((g) => (
+          <div key={g.key} className="rounded-lg border border-slate-800 bg-slate-950/40 p-3">
+            <div className="mb-2 text-sm font-semibold text-slate-200">{g.label}</div>
+            <div className="space-y-1">
+              {g.items.map((c) => {
+                const meta = rankMeta.get(c.rank);
+                if (!meta) return null;
+                const checked = !!visibleRanks[c.rank];
+                return (
+                  <label key={c.rank} className="flex cursor-pointer items-center gap-2 text-xs text-slate-300">
+                    <input
+                      type="checkbox"
+                      checked={checked}
+                      onChange={(e) => setVisibleRanks((prev) => ({ ...prev, [c.rank]: e.target.checked }))}
+                    />
+                    <span
